import os
B=r'D:/repository'
out=[]
def rd(rel):
    p=os.path.join(B,rel)
    return open(p,encoding='utf-8',errors='ignore').read() if os.path.isfile(p) else None

# #0 read real utils/index.js
t=rd('苏住房C/zhi2-mobile-shimin/src/utils/index.js')
out.append('=== #0 src/utils/index.js exists='+str(t is not None))
if t:
    for kw in ['shouldSkip','IdType','RealName','FormLocal','PROD','实名']:
        out.append('  '+kw+' count='+str(t.count(kw)))
    # print RealName related lines
    for i,l in enumerate(t.splitlines(),1):
        if 'RealName' in l or 'IdType' in l or 'FormLocal' in l or '实名' in l:
            out.append('   L%d %s'%(i,l.strip()[:140]))

# #7 series.line exact in min file
t=rd('泰兴小程序/src/staff/pages/components/echarts-uniapp/echarts.min.js')
out.append('=== #7 echarts.min.js exists='+str(t is not None))
if t:
    for kw in ['series.line','"line"',"'line'",'series.bar','series.pie','series.gauge']:
        out.append('  '+kw+' count='+str(t.count(kw)))

# #36 Navbar.vue nav indicator symbols
t=rd('门户/zhi2-web-admin/src/layout/components/Navbar.vue')
out.append('=== #36 Navbar.vue exists='+str(t is not None))
if t:
    for kw in ['updateNavIndicator','normalizeMenuPath','ResizeObserver','requestAnimationFrame','animate','indicator']:
        out.append('  '+kw+' count='+str(t.count(kw)))

# #8 whole-repo search for apiV3Normalize / ACTION_PARAM_KEY_OVERRIDES
out.append('=== #8 whole repo symbol scan')
SKIP={'node_modules','.git','dist','unpackage','.idea','.vscode'}
for dp,dirs,files in os.walk(B):
    dirs[:]=[d for d in dirs if d not in SKIP]
    for fn in files:
        if not fn.endswith(('.js','.ts','.vue','.mjs')): continue
        p=os.path.join(dp,fn)
        try:
            if os.path.getsize(p)>3*1024*1024: continue
            s=open(p,encoding='utf-8',errors='ignore').read()
        except: continue
        if 'apiV3Normalize' in s or 'ACTION_PARAM_KEY_OVERRIDES' in s:
            out.append('  HIT '+os.path.relpath(p,B))
            for i,l in enumerate(s.splitlines(),1):
                if 'apiV3Normalize' in l or 'ACTION_PARAM_KEY_OVERRIDES' in l:
                    out.append('     L%d %s'%(i,l.strip()[:120]))
            break
open(r'C:/Users/Administrator/.dsh/cache/memory-audit/final_out.txt','w',encoding='utf-8').write('\n'.join(out))
print('lines',len(out))

